// X86 Thread Local Storage (TLS) setup
struct user_desc {
    unsigned int entry_number; // GDT index
    unsigned int base_addr;    // Start of TLS block
    unsigned int limit;
    unsigned int flags;
};

// Allocate a GDT entry and set its base address
void* thread_data_ptr = get_tls_base();

struct user_desc tls_entry = {
    .entry_number = -1, // Request kernel assignment
    .base_addr = (unsigned int)thread_data_ptr,
    .limit = 0xFFFFF,
    .flags = 0x4092, // Standard TLS flags
};

// Returns 0 on success (or GDT index > 0)
long result = syscall(SYS_set_thread_area, &tls_entry);

// entry_number is updated by the kernel
int gdt_index = tls_entry.entry_number;

